import {
  MeshBasicNodeMaterial,
  Mesh,
  PlaneGeometry,
  Vector3,
  Euler,
} from 'three/webgpu';

export default function createNode(config, ctx) {
  const {
    scenePosition = { x: 3.2, y: -0.3, z: 0 },
    sceneRotation = { x: 0, y: 0, z: 0 },
    sceneScale = { x: 1, y: 1, z: 1 },
    imageUrl = '/prism-mock/home/nodes/feature-card.png',
    atlasSourceRect = { x: 0, y: 0, width: 512, height: 320 },
  } = config;

  // Determine plane dimensions from the atlas source rect aspect ratio.
  const aspectRatio = atlasSourceRect.width / atlasSourceRect.height;
  const width = 1.5;
  const height = width / aspectRatio;

  const geometry = new PlaneGeometry(width, height);
  const texture = ctx.textureLoader.load(imageUrl);

  // If the texture is part of a larger atlas, we would set repeat and offset here.
  // Since no full atlas size is provided, we assume the texture is the exact card.
  const material = new MeshBasicNodeMaterial({
    map: texture,
    color: 0xffffff,
    transparent: false,
    side: 2, // DoubleSide
  });

  const mesh = new Mesh(geometry, material);

  mesh.position.set(scenePosition.x, scenePosition.y, scenePosition.z);
  mesh.rotation.set(
    sceneRotation.x,
    sceneRotation.y,
    sceneRotation.z
  );
  mesh.scale.set(sceneScale.x, sceneScale.y, sceneScale.z);

  // No interactive handlers per spec
  mesh.userData.handlers = {};

  // Cleanup: dispose geometry, material, and texture
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return mesh;
}
